"""Original source headers must be generated by real held selection events."""
import copy
import json
import hashlib
from pathlib import Path
import subprocess
import sys
import tempfile
import unittest

ROOT=Path(__file__).resolve().parents[1]
EVIDENCE=ROOT/'docs/validation/otis-90-minute'

class HistoricalLiveSelectionTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.temporary=tempfile.TemporaryDirectory()
        folder=Path(cls.temporary.name);output=folder/'history.json'
        subprocess.run([sys.executable,str(ROOT/'tools/build_otis_history_manifest.py'),'--workspace',str(folder/'work'),'--output',str(output)],check=True,capture_output=True)
        cls.manifest=json.loads(output.read_text())
        cls.steps=cls.manifest['steps']

    @classmethod
    def tearDownClass(cls):cls.temporary.cleanup()

    def test_total_revenue_held_extension_keeps_visible_intermediate_dimensions(self):
        expected=[('11:23.883','1R x 4C'),('11:24.483','1R x 6C'),('11:24.933','1R x 9C')]
        for time,header in expected:
            with self.subTest(time=time):
                matches=[r for r in self.steps if r['videoTime']==time and r['action'].get('type')=='key_sequence' and r['action'].get('keys')==['Shift+Right'] and r['action'].get('releaseModifiers') is False]
                self.assertEqual(len(matches),1,'The fixed source pointer and changing dimensions require a real held Shift extension')
                self.assertEqual(matches[0].get('expect',{}).get('nameBoxText'),header)
        self.assertFalse(any('11:24.000'<=r['videoTime']<='11:25.500' and r['action'].get('target')=='formula.name' for r in self.steps),'Typing range addresses cannot replace source live dimension headers')


class RemainingLiveSelectionTests(HistoricalLiveSelectionTests):
    def test_raw_operating_profit_drag_keeps_anchor_and_both_directions(self):
        for time,address,header in [('09:58.400','I12','7R x 9C'),('09:58.533','I11','8R x 9C'),('09:59.833','I22','5R x 9C')]:
            with self.subTest(time=time):
                r=[r for r in self.steps if r['videoTime']==time and r['action']=={'type':'mouse_cell','address':address,'gesture':'move'}]
                self.assertEqual(len(r),1,'Upward overshoot, reduction and downward extension must remain a single genuine drag')
                self.assertEqual(r[0]['expect']['nameBoxText'],header)
                self.assertEqual((r[0]['expect']['row'],r[0]['expect']['column']),(18,1))

    def test_pension_drag_starts_before_the_first_range_and_keeps_every_visible_extent(self):
        expected=[
            ('10:41.267','A19','press','A19'),
            ('10:41.433','B19','move','1R x 2C'),
            ('10:41.500','C20','move','2R x 3C'),
            ('10:41.533','D20','move','2R x 4C'),
            ('10:41.567','F20','move','2R x 6C'),
            ('10:41.600','G20','move','2R x 7C'),
            ('10:41.667','H19','move','1R x 8C'),
            ('10:41.733','I19','move','1R x 9C'),
            ('10:42.700','I20','move','2R x 9C'),
            ('10:42.900','I21','move','3R x 9C'),
            ('10:42.967','E20','move','2R x 5C'),
            ('10:43.000','F20','move','2R x 6C'),
            ('10:43.067','G20','move','2R x 7C'),
            ('10:43.167','I20','move','2R x 9C'),
            ('10:43.800','I20','release','A19'),
        ]
        for time,address,gesture,header in expected:
            with self.subTest(time=time):
                matches=[r for r in self.steps if r['videoTime']==time and r['action']=={'type':'mouse_cell','address':address,'gesture':gesture}]
                self.assertEqual(len(matches),1,'The original30fps frame shows this extent during one continuous drag')
                r=matches[0]
                self.assertEqual(r['expect'],{'row':19,'column':1,'nameBoxText':header})
                self.assertTrue(Path(r['evidence']['sourceFrame']).is_file())
                self.assertIn('history-0103',r['evidence']['sourceObservationIds'])
        self.assertFalse(any('10:41.267'<=r['videoTime']<='10:43.800' and r['action'].get('target')=='formula.name' for r in self.steps),'Completed Name Box selections would interrupt the source held drag and replace its dimension headers')

    def test_pre_tax_border_range_retains_its_two_row_overshoot(self):
        r=[r for r in self.steps if r['videoTime']=='11:33.667' and r['action']=={'type':'mouse_cell','address':'F17','gesture':'move'}]
        self.assertEqual(len(r),1,'The source visibly overshoots into a second row before returning to row16')
        self.assertEqual(r[0]['expect']['nameBoxText'],'2R x 5C')

    def test_header_drag_extends_upward_into_row_one_before_reducing(self):
        for time,header in [('15:15.383','2R x 2C'),('15:15.483','2R x 3C'),('15:15.683','1R x 3C')]:
            self.assertTrue(any(r['videoTime']==time and r.get('expect',{}).get('nameBoxText')==header for r in self.steps),'Actual source header substate must be native and independently checked')

class FinalRawSelectionExpectationTests(HistoricalLiveSelectionTests):
    def test_source_handoff_keeps_singleton_E51_on_cash_flows_at_A37(self):
        r=next(r for r in self.steps if r['id'].endswith('source-handoff-viewport'))
        self.assertEqual(r['expect'],{'topRow':37,'firstColumn':1,'row':51,'column':5,'sheetName':'cash flows','nameBoxText':'E51'})

