    def test_post12_source_restoration_rejects_modified_approved_records(self):
        for identifier,field in [('historical-early-b11-interim-commit','input'),
                                 ('historical-zero-return-c37','navigation'),
                                 ('historical-remaining-early-date-qa-settled','qa-dwell')]:
            with self.subTest(source=identifier):
                records=copy.deepcopy(self.steps)
                changed=next(s for s in records if s['id']==identifier)
                if field=='input':changed['expect']['cells'][0]['input']='Unreviewed label'
                elif field=='qa-dwell':changed['action']['dwellMs']=0
                else:changed['action']['keys']=['Right']
                with self.assertRaisesRegex(AssertionError,'exact reviewed after-image'):
                    self.restore_reviewed_post12_source_records(records)

    def restore_reviewed_b59_commit_records(self, records):
        # Restore only the independently proved retained-cell commit and its
        # source-observation refinement before applying every older guard.
        path=EVIDENCE/'post-attempt10-b59-commit-retention/exact-generated-action-delta.json'
        self.assertEqual(hashlib.sha256(path.read_bytes()).hexdigest(),
                         '9fcb3b73d654931cd0df86597883b3894bf4b75aee9c62c25ff9d93ef51ca6d7')
        delta=json.loads(path.read_text())['default']
        self.assertEqual((delta['beforeCount'],delta['afterCount']),(4398,4399))
        self.assertEqual({r['id'] for r in delta['changedRecords']},
                         {'historical-02828-commit','historical-04153-source-insert'})
        self.assertEqual(delta['removedRecords'],[])
        self.assertEqual([r['id'] for r in delta['addedRecords']],
                         ['historical-text-checkpoint-b59-enter-1725500'])
        prior_path=EVIDENCE/'post-attempt10-b59-commit-retention/before/default-generated-history.json'
        self.assertEqual(hashlib.sha256(prior_path.read_bytes()).hexdigest(),
                         '43443238358d80995806152c1a077115c3f3cecfb8d719c5e9b08b1aa7e8498a')
        prior=json.loads(prior_path.read_text())['steps'];old={r['id']:r for r in prior}
        current={r['id']:r for r in records};restored=copy.deepcopy(records)
        for change in delta['changedRecords']:
            self.assertEqual(change['before'],old[change['id']])
            self.assertEqual(current[change['id']],change['after'],
                             'Only the exact reviewed B59 commit/source after-image may be restored')
            restored[next(i for i,r in enumerate(restored) if r['id']==change['id'])]=copy.deepcopy(change['before'])
        for addition in delta['addedRecords']:
            self.assertEqual(current[addition['id']],addition,
                             'The uncommitted B59 draft checkpoint must equal its exact reviewed after-image')
            restored=[r for r in restored if r['id']!=addition['id']]
        self.assertEqual([r['id'] for r in restored],[r['id'] for r in prior],
                         'B59 restoration cannot conceal any unrelated record reorder')
        return restored

    def test_original_digest_still_rejects_unrelated_record_reordering(self):
        original=self.steps
        self.steps=copy.deepcopy(original)
        try:
            first=next(i for i,r in enumerate(self.steps) if r['id']=='intro-raw-sheet-001')
            second=next(i for i,r in enumerate(self.steps) if r['id']=='intro-raw-sheet-002')
            self.steps[first],self.steps[second]=self.steps[second],self.steps[first]
            with self.assertRaises(AssertionError,
                                   msg='Approved retiming must never normalize an unrelated tab traversal reorder'):
                self.test_borders_retiming_preserves_every_other_historical_action()
        finally:
            self.steps=original

    def test_modal_header_normalization_rejects_an_unreviewed_child(self):
        original=self.steps
        self.steps=copy.deepcopy(original)
        try:
            modal=next(r for r in self.steps if r['evidence'].get('eventId')=='history-0201'
                       and r['action']['type']=='modal')
            modal['action']['steps'][0]['action']['target']='pasteSpecial.values'
            with self.assertRaisesRegex(AssertionError,'exact reviewed after-image'):
                self.test_borders_retiming_preserves_every_other_historical_action()
        finally:
            self.steps=original

